/* libnativedisplay for the arm64 native runtime (PLAN P7): the device library asks SurfaceFlinger for vsync over binder
 * (ComposerService); there is none here, so Choreographer is a software 60 Hz clock on a timerfd. HWUI's RenderThread
 * polls getFd() and calls handlePendingEvents(); callbacks posted with postVsyncCallback() run then. Every other export of
 * the real library (ASurfaceTexture, ADisplay, ...) is a weak do-nothing stub generated by scripts/build-native-arm64.sh,
 * so anything that links against it still loads. Loaded through bionic_translation's cfg.d (libnativedisplay.so). */
#define _GNU_SOURCE
#include <stdint.h>
#include <stdlib.h>
#include <sys/timerfd.h>
#include <time.h>
#include <unistd.h>

#define INTERVAL_NS 16666667

typedef void (*vsync_cb)(const void *data, void *user);
struct frame_data { int64_t frame_time_ns; };
struct choreographer { int fd; vsync_cb cb; void *user; struct frame_data data; };

static int64_t now_ns(void)
{
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return (int64_t)ts.tv_sec * 1000000000 + ts.tv_nsec;
}

void *AChoreographer_create(void)
{
    struct choreographer *c = calloc(1, sizeof *c);
    c->fd = timerfd_create(CLOCK_MONOTONIC, TFD_CLOEXEC | TFD_NONBLOCK);
    return c;
}

void AChoreographer_destroy(struct choreographer *c) { close(c->fd); free(c); }
int AChoreographer_getFd(struct choreographer *c) { return c->fd; }

void AChoreographer_postVsyncCallback(struct choreographer *c, vsync_cb cb, void *user)
{
    c->cb = cb;
    c->user = user;
    struct itimerspec t = { .it_value = { 0, INTERVAL_NS } };
    timerfd_settime(c->fd, 0, &t, NULL);
}

void AChoreographer_handlePendingEvents(struct choreographer *c, void *data)
{
    (void)data;
    uint64_t expirations;
    if (read(c->fd, &expirations, sizeof expirations) != sizeof expirations || !c->cb) return;
    vsync_cb cb = c->cb;
    c->cb = NULL;
    c->data.frame_time_ns = now_ns();
    cb(&c->data, c->user);
}

void AChoreographer_registerRefreshRateCallback(void *c, void *cb, void *user) { (void)c; (void)cb; (void)user; }
int64_t _ZN7android31AChoreographer_getFrameIntervalEPK14AChoreographer(const void *c) { (void)c; return INTERVAL_NS; }

int64_t AChoreographerFrameCallbackData_getFrameTimeNanos(const struct frame_data *d) { return d->frame_time_ns; }
size_t AChoreographerFrameCallbackData_getFrameTimelinesLength(const void *d) { (void)d; return 1; }
size_t AChoreographerFrameCallbackData_getPreferredFrameTimelineIndex(const void *d) { (void)d; return 0; }
int64_t AChoreographerFrameCallbackData_getFrameTimelineVsyncId(const struct frame_data *d, size_t i) { (void)i; return d->frame_time_ns / INTERVAL_NS; }
int64_t AChoreographerFrameCallbackData_getFrameTimelineExpectedPresentationTimeNanos(const struct frame_data *d, size_t i) { (void)i; return d->frame_time_ns + INTERVAL_NS; }
int64_t AChoreographerFrameCallbackData_getFrameTimelineDeadlineNanos(const struct frame_data *d, size_t i) { (void)i; return d->frame_time_ns + INTERVAL_NS; }
